function LeastTime(tasks: string; n: integer): integer;
begin
  var count := new Dictionary<char, integer>;
  foreach var task in tasks do
  begin
    if count.ContainsKey(task) then
      count[task] += 1
    else
      count[task] := 1;
  end;

  var maxHeap := new List<integer>;
  foreach var cnt in count.Values do
    maxHeap.Add(-cnt);
  maxHeap.Sort;

  var q := new Queue<(integer, integer)>;
  var t := 0;

  while (q.Count > 0) or (maxHeap.Count > 0) do
  begin
    t += 1;
    if maxHeap.Count > 0 then
    begin
      var cnt := -maxHeap.First + 1;
      maxHeap.RemoveAt(0);
      if cnt > 0 then
        q.Enqueue((cnt, t + n));
    end;

    if (q.Count > 0) and (q.Peek.Item2 = t) then
    begin
      var el := q.Dequeue.Item1;
      maxHeap.Add(-el);
      maxHeap.Sort;
    end;
  end;

  Result := t;
end;

