procedure Backtrack(i: integer; current: string; const S: string; var result: List<string>);
begin
  if i >= S.Length then
  begin
    result.Add(current);
    exit;
  end;

  Backtrack(i + 1, current + S[i + 1], S, result);

  if S[i + 1].IsLetter then
  begin
    if S[i + 1].IsLower then
      Backtrack(i + 1, current + S[i + 1].ToUpper, S, result)
    else
      Backtrack(i + 1, current + S[i + 1].ToLower, S, result);
  end;
end;

function CasePermutation(S: string): List<string>;
