  Backtrack(0, '', S, res);
  Result := res;
end;

function MaxSumTwoSubarrays(A: array of integer; L, M: integer): integer;
begin
  var preSum := ArrFill(A.Length + 1, 0);
  for var i := 1 to preSum.Length - 1 do
    preSum[i] := preSum[i - 1] + A[i - 1];

  var Lmax := preSum[L];
  var Mmax := preSum[M];
  var ans := preSum[L + M];

  for var i := L + M + 1 to preSum.Length - 1 do
  begin
    Lmax := Max(Lmax, preSum[i - M] - preSum[i - M - L]);
    Mmax := Max(Mmax, preSum[i - L] - preSum[i - L - M]);
    ans := Max(ans, Lmax + preSum[i] - preSum[i - M], Mmax + preSum[i] - preSum[i - L]);
  end;

  Result := ans;
end;

