procedure Permute(perm: List<integer>; remainingNums: List<integer>; var results: List<List<integer>>);
begin
  if remainingNums.Count = 0 then
  begin
    results.Add(new List<integer>(perm));
    exit;
  end;

  for var i := 0 to remainingNums.Count - 1 do
  begin
    if (i > 0) and (remainingNums[i] = remainingNums[i - 1]) then
      continue;

    var newPerm := new List<integer>(perm);
    newPerm.Add(remainingNums[i]);

    var newRemainingNums := new List<integer>(remainingNums);
    newRemainingNums.RemoveAt(i);

    Permute(newPerm, newRemainingNums, results);
  end;
end;

function GeneratePerms(nums: array of integer): List<List<integer>>;
begin
