end;

function IsBalancedTree(root: BinaryTree): boolean;
begin
  if root = nil then
  begin
    Result := True;
    exit;
  end;

  var leftHeight := Height(root.Left);
  var rightHeight := Height(root.Right);

  if (Abs(leftHeight - rightHeight) <= 1) and IsBalancedTree(root.Left) and IsBalancedTree(root.Right) then
    Result := True
  else
    Result := False;
end;

