      if s[i] = '1' then
        count0 += 1
      else
        count1 += 1;
    end
    else
    begin
      if s[i] = '1' then
        count1 += 1
      else
        count0 += 1;
    end;
  end;

  Result := Min(count0, count1);
end;

function FindMaxSquare(matrix: array of array of integer): integer;
begin
  if matrix.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var rows := matrix.Length;
  var cols := matrix[0].Length;
  var dp := new integer[rows, cols];
  var maxSide := 0;

  for var i := 0 to rows - 1 do
    for var j := 0 to cols - 1 do
    begin
      if matrix[i][j] = 1 then
      begin
        if (i = 0) or (j = 0) then
          dp[i, j] := 1
        else
          dp[i, j] := Min(Min(dp[i-1, j], dp[i, j-1]), dp[i-1, j-1]) + 1;

        maxSide := Max(maxSide, dp[i, j]);
      end;
    end;

  Result := maxSide;
end;

function Dist(p1, p2: (real, real)): real;
