  for var i := 0 to 3 do
    for var j := i + 1 to 3 do
      distances.Add(Dist(points[i], points[j]));

  distances.Sort;

  Result := (distances[0] = distances[1]) and (distances[1] = distances[2]) and 
            (distances[2] = distances[3]) and (distances[4] = distances[5]) and 
            (distances[0] <> 0);
end;

