function FindMaxLengthSubarray(nums: array of integer; k: integer): integer;
begin
  var maxLength := 0;
  var prefixSum := new Dictionary<integer, integer>;
  prefixSum[0] := -1;
  var sumSoFar := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    sumSoFar += nums[i];

    if prefixSum.ContainsKey(sumSoFar - k) then
      maxLength := Max(maxLength, i - prefixSum[sumSoFar - k]);

    if not prefixSum.ContainsKey(sumSoFar) then
      prefixSum[sumSoFar] := i;
  end;

  Result := maxLength;
end;

function TrapRainwater(heights: array of integer): integer;
begin
  var n := heights.Length;
  if n < 3 then
  begin
    Result := 0;
    exit;
  end;

  var leftMax := ArrFill(n, heights[0]);
  for var i := 1 to n - 1 do
    leftMax[i] := Max(leftMax[i - 1], heights[i]);

  var rightMax := ArrFill(n, heights[n - 1]);
  for var i := n - 2 downto 0 do
    rightMax[i] := Max(rightMax[i + 1], heights[i]);

  var res := 0;
  for var i := 0 to n - 1 do
    res += Min(leftMax[i], rightMax[i]) - heights[i];

  Result := res;
end;

function NumToRoman(num: integer): string;
begin
  var val := |1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1|;
  var syb := |'M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I'|;

  var romanNum := '';
  var i := 0;
  var tempNum := num;

  while tempNum > 0 do
  begin
    for var j := 1 to tempNum div val[i] do
    begin
      romanNum += syb[i];
      tempNum -= val[i];
    end;
    i += 1;
  end;

  Result := romanNum;
end;

function CountFormableStrings(words: array of string; chars: string): integer;
begin
  var count := 0;
  var charsCounter := new Dictionary<char, integer>;

  foreach var ch in chars do
  begin
    if charsCounter.ContainsKey(ch) then
      charsCounter[ch] += 1
    else
      charsCounter[ch] := 1;
  end;

  foreach var word in words do
  begin
    var wordCounter := new Dictionary<char, integer>;
    foreach var ch in word do
    begin
      if wordCounter.ContainsKey(ch) then
        wordCounter[ch] += 1
      else
        wordCounter[ch] := 1;
    end;

    var canForm := true;
    foreach var kv in wordCounter do
    begin
      if (not charsCounter.ContainsKey(kv.Key)) or (charsCounter[kv.Key] < kv.Value) then
      begin
        canForm := false;
        break;
      end;
    end;

    if canForm then
      count += word.Length;
  end;

  Result := count;
end;

function MaxNonAdjSum(nums: array of integer): integer;
begin
  if nums.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var incl := 0;
  var excl := 0;

  foreach var i in nums do
  begin
    var newExcl := Max(excl, incl);
    incl := excl + i;
    excl := newExcl;
  end;

  Result := Max(excl, incl);
end;

function CanTransformString(s, t: string; k: integer): boolean;
begin
  if s.Length <> t.Length then
  begin
    Result := false;
    exit;
  end;

  if s = t then
  begin
    Result := true;
    exit;
  end;

  var counts := new Dictionary<integer, integer>;

  for var i := 0 to s.Length - 1 do
  begin
    var shift := (Ord(t[i]) - Ord(s[i])) mod 26;
    if shift < 0 then
      shift += 26;

    if shift > 0 then
    begin
      if counts.ContainsKey(shift) then
        counts[shift] += 1
      else
        counts[shift] := 1;
    end;
  end;

  foreach var kv in counts do
  begin
    var totalShift := kv.Key + 26 * (kv.Value - 1);
    if totalShift > k then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := true;
end;

function PascalsTriangle(numRows: integer): List<List<integer>>;
