    for var j := 0 to i do
      row.Add(1);
    res.Add(row);
  end;

  for var i := 0 to numRows - 1 do
    for var j := 1 to i - 1 do
      res[i][j] := res[i-1][j-1] + res[i-1][j];

  Result := res;
end;

