  var n := cost[0].Length;

  for var i := 1 to n - 1 do
    cost[0][i] += cost[0][i-1];

  for var i := 1 to m - 1 do
    cost[i][0] += cost[i-1][0];

  for var i := 1 to m - 1 do
    for var j := 1 to n - 1 do
      cost[i][j] += Min(cost[i-1][j], cost[i][j-1]);

  Result := cost[m-1][n-1];
end;

