function FindQuadruplets(nums: array of integer; target: integer): List<List<integer>>;
begin
  var res := new List<List<integer>>;
  var tempNums := nums.ToList;
  tempNums.Sort;

  for var i := 0 to tempNums.Count - 4 do
  begin
    if (i > 0) and (tempNums[i] = tempNums[i-1]) then
      continue;

    for var j := i + 1 to tempNums.Count - 3 do
    begin
      if (j > i + 1) and (tempNums[j] = tempNums[j-1]) then
        continue;

      var l := j + 1;
      var r := tempNums.Count - 1;

      while l < r do
      begin
        var total := tempNums[i] + tempNums[j] + tempNums[l] + tempNums[r];
        if total < target then
          l += 1
        else if total > target then
          r -= 1
        else
        begin
          res.Add(new List<integer>([tempNums[i], tempNums[j], tempNums[l], tempNums[r]]));
          while (l < r) and (tempNums[l] = tempNums[l + 1]) do
            l += 1;
          while (l < r) and (tempNums[r] = tempNums[r - 1]) do
            r -= 1;
          l += 1;
          r -= 1;
        end;
      end;
    end;
  end;

  Result := res;
end;

