function NextGreatestNumber(n: integer): integer;
begin
  var numStr := n.ToString;
  var length := numStr.Length;
  var i := length - 2;

  while i >= 0 do
  begin
    if numStr[i + 1] > numStr[i] then
      break;
    i -= 1;
  end;

  if i = -1 then
  begin
    Result := -1;
    exit;
  end;

  var j := length - 1;
  while numStr[j] <= numStr[i] do
    j -= 1;

  while (j > 0) and (numStr[j] = numStr[j - 1]) do
    j -= 1;

  var chars := numStr.ToCharArray;
  var temp := chars[i];
  chars[i] := chars[j];
  chars[j] := temp;

  var tail := chars.Skip(i + 1).Reverse.ToArray;
  for var k := i + 1 to length - 1 do
    chars[k] := tail[k - i - 1];

  Result := StrToInt(new string(chars));
end;

function FindLongestEqualSubarray(nums: array of integer): integer;
begin
  var d := new Dictionary<integer, integer>;
  d[0] := -1;
  var sum := 0;
  var res := 0;

  for var i := 0 to nums.Length - 1 do
  begin
    sum += 2 * nums[i] - 1;
    if d.ContainsKey(sum) then
      res := Max(res, i - d[sum])
    else
      d[sum] := i;
  end;

  Result := res;
end;

function StringMultiplication(num1, num2: string): string;
begin
  if (num1 = '0') or (num2 = '0') then
  begin
    Result := '0';
    exit;
  end;

  var len1 := num1.Length;
  var len2 := num2.Length;
  var res := ArrFill(len1 + len2, 0);

  for var i := len1 - 1 downto 0 do
    for var j := len2 - 1 downto 0 do
    begin
      var mul := (Ord(num1[i + 1]) - Ord('0')) * (Ord(num2[j + 1]) - Ord('0'));
      var p1 := i + j;
      var p2 := i + j + 1;
      var sum := mul + res[p2];

      res[p1] += sum div 10;
      res[p2] := sum mod 10;
    end;

  var resultStr := string.Join('', res.Select(x -> x.ToString));
  Result := resultStr.TrimStart('0');
end;

