function FindMaxOperations(nums: array of integer; k: integer): integer;
begin
  var mp := new Dictionary<integer, integer>;
  var ans := 0;

  foreach var i in nums do
  begin
    if i >= k then
      continue;

    var m := k - i;
    if mp.ContainsKey(m) and (mp[m] >= 1) then
    begin
      ans += 1;
      mp[m] -= 1;
    end
    else
    begin
      if mp.ContainsKey(i) then
        mp[i] += 1
      else
        mp[i] := 1;
    end;
  end;

  Result := ans;
end;

