function GetMaxLength(nums: array of integer; startIndex: integer): integer;
begin
  var j := startIndex;
  var n := 0;
  var max1 := 0;
  var n_s := -1;
  var n_e := -1;

  while (j < nums.Length) and (nums[j] <> 0) do
  begin
    if nums[j] < 0 then
    begin
      if n_s = -1 then
        n_s := j;
      n_e := j;
      n += 1;
    end;

    if n mod 2 = 0 then
      max1 := Max(max1, j - startIndex + 1)
    else
    begin
      max1 := Max(max1, j - n_s);
      max1 := Max(max1, n_e - startIndex);
    end;
    j += 1;
  end;

  if (j + 1 < nums.Length - 1) then
    Result := Max(max1, GetMaxLength(nums, j + 1))
  else
    Result := max1;
end;

function MaxPositiveProduct(nums: array of integer): integer;
