  for var i := 2 to Round(Sqrt(n)) do
  begin
    if n mod i = 0 then
    begin
      if i = n div i then
        divisors.Add(i)
      else
      begin
        divisors.Add(i);
        divisors.Add(n div i);
      end;
    end;
  end;

  Result := divisors.Sum;
end;

