function FindMedianSortedArrays(nums1, nums2: array of integer): real;
begin
  var merged := new List<integer>;
  var i := 0;
  var j := 0;

  while (i < nums1.Length) and (j < nums2.Length) do
  begin
    if nums1[i] < nums2[j] then
    begin
      merged.Add(nums1[i]);
      i += 1;
    end
    else
    begin
      merged.Add(nums2[j]);
      j += 1;
    end;
  end;

  while i < nums1.Length do
  begin
    merged.Add(nums1[i]);
    i += 1;
  end;

  while j < nums2.Length do
  begin
    merged.Add(nums2[j]);
    j += 1;
  end;

  var n := merged.Count;
  if n mod 2 = 0 then
    Result := (merged[n div 2 - 1] + merged[n div 2]) / 2
  else
    Result := merged[n div 2];
end;

