function Dfs(index, count: integer; hasPre, root: boolean; const slices: array of integer): integer;
begin
  if index = slices.Length then
  begin
    if (count <> slices.Length div 3) or (hasPre and root) then
      Result := integer.MinValue
    else
      Result := 0;
    exit;
  end;

  var res := Dfs(index + 1, count, false, root, slices);
  if (not hasPre) and (count + 1 <= slices.Length div 3) then
    res := Max(res, Dfs(index + 1, count + 1, true, root, slices) + slices[index]);

  Result := res;
end;

function MaxSizeSlices(slices: array of integer): integer;
