function IsMiddle(pointX2, pointY2: ((real, real), (real, real))): boolean;
begin
  Result := ((pointX2.Item1.Item1 + pointX2.Item2.Item1) / 2 = (pointY2.Item1.Item1 + pointY2.Item2.Item1) / 2) and
            ((pointX2.Item1.Item2 + pointX2.Item2.Item2) / 2 = (pointY2.Item1.Item2 + pointY2.Item2.Item2) / 2);
end;

function MinAreaFreeRect(points: array of (real, real)): real;
begin
  var dictsDistance := new Dictionary<real, List<((real, real), (real, real))>>;

  for var i := 0 to points.Length - 1 do
    for var j := i + 1 to points.Length - 1 do
    begin
      var pointsDistance := Distance(points[i], points[j]);
      if not dictsDistance.ContainsKey(pointsDistance) then
        dictsDistance[pointsDistance] := new List<((real, real), (real, real))>;
      dictsDistance[pointsDistance].Add((points[i], points[j]));
    end;

  var minArea := real.MaxValue;

  foreach var key in dictsDistance.Keys do
  begin
    if dictsDistance[key].Count < 2 then
      continue;

    for var i1 := 0 to dictsDistance[key].Count - 2 do
      for var i2 := i1 + 1 to dictsDistance[key].Count - 1 do
      begin
        var points4 := Arr(dictsDistance[key][i1], dictsDistance[key][i2]);
        if IsMiddle(points4[0], points4[1]) then
        begin
          var p2 := points4[0].Item1;
          var (p1, p3) := points4[1];
          var area := Distance(p2, p1) * Distance(p2, p3);
          minArea := Min(minArea, area);
        end;
      end;
  end;

  if minArea = real.MaxValue then
    Result := 0
  else
    Result := minArea;
end;

function CyclicSort(nums: array of integer): boolean;
begin
  var n := nums.Length;
  if n <= 1 then
  begin
    Result := true;
    exit;
  end;

  var disordered := 0;
  for var i := 1 to n - 1 do
  begin
    if nums[i-1] > nums[i] then
      disordered += 1;
  end;

  if nums[n-1] > nums[0] then
    disordered += 1;

  Result := disordered <= 1;
end;

