procedure ApplyOperator(operands: List<integer>; op: char);
begin
  var b := operands[operands.Count - 1];
  operands.RemoveAt(operands.Count - 1);
  var a := operands[operands.Count - 1];
  operands.RemoveAt(operands.Count - 1);

  case op of
    '+': operands.Add(a + b);
    '-': operands.Add(a - b);
    '*': operands.Add(a * b);
    '/': operands.Add(a div b);
  end;
end;

function GreaterPrecedence(op1, op2: char): boolean;
begin
  var precedence := new Dictionary<char, integer>;
  precedence['+'] := 1; precedence['-'] := 1;
  precedence['*'] := 2; precedence['/'] := 2;
  Result := precedence[op1] > precedence[op2];
end;

function Evaluate(expr: string): integer;
begin
  var operands := new List<integer>;
  var operators := new List<char>;
  var i := 0;

  while i < expr.Length do
  begin
    if expr[i + 1] = ' ' then
    begin
      i += 1;
      continue;
    end;

    if expr[i + 1].IsDigit then
    begin
      var val := 0;
      while (i < expr.Length) and expr[i + 1].IsDigit do
      begin
        val := (val * 10) + StrToInt(expr[i + 1]);
        i += 1;
      end;
      operands.Add(val);
      continue;
    end
    else if expr[i + 1] = '(' then
      operators.Add(expr[i + 1])
    else if expr[i + 1] = ')' then
    begin
      while operators[operators.Count - 1] <> '(' do
      begin
        ApplyOperator(operands, operators[operators.Count - 1]);
        operators.RemoveAt(operators.Count - 1);
      end;
      operators.RemoveAt(operators.Count - 1);
    end
    else
    begin
      while (operators.Count > 0) and (operators[operators.Count - 1] <> '(') and
            GreaterPrecedence(operators[operators.Count - 1], expr[i + 1]) do
      begin
        ApplyOperator(operands, operators[operators.Count - 1]);
        operators.RemoveAt(operators.Count - 1);
      end;
      operators.Add(expr[i + 1]);
    end;
    i += 1;
  end;

  while operators.Count > 0 do
  begin
    ApplyOperator(operands, operators[operators.Count - 1]);
    operators.RemoveAt(operators.Count - 1);
  end;

  Result := operands[0];
end;

function CalculateExpression(expression: string): integer;
