    lucas[0] := 2;
    lucas[1] := 1;
    for var i := 2 to n do
      lucas[i] := lucas[i-1] + lucas[i-2];
    Result := lucas[n];
  end;
end;

function MaxKSumPairs(nums: array of integer; k: integer): integer;
