  var tempNums := nums.ToList;
  tempNums.Sort;
  var left := 0;
  var right := tempNums.Count - 1;

  while left < right do
  begin
    if tempNums[left] + tempNums[right] = k then
    begin
      pairs += 1;
      left += 1;
      right -= 1;
    end
    else if tempNums[left] + tempNums[right] < k then
      left += 1
    else
      right -= 1;
  end;

  Result := pairs;
end;

function FindSecondHighest(lst: array of integer): integer;
