  var highest := integer.MinValue;
  var secondHighest := integer.MinValue;

  foreach var num in lst do
  begin
    if num > highest then
    begin
      secondHighest := highest;
      highest := num;
    end
    else if (num > secondHighest) and (num <> highest) then
      secondHighest := num;
  end;

  if secondHighest = integer.MinValue then
    Result := -1
  else
    Result := secondHighest;
end;

