  stack.Add(-1);

  for var i := 0 to s.Length - 1 do
  begin
    if s[i + 1] = '(' then
      stack.Add(i)
    else
    begin
      stack.RemoveAt(stack.Count - 1);
      if stack.Count = 0 then
        stack.Add(i)
      else
        maxLen := Max(maxLen, i - stack[stack.Count - 1]);
    end;
  end;

  Result := maxLen;
end;

