function ClosestSquareRoot(x: integer): integer;
begin
  if x = 0 then
  begin
    Result := 0;
    exit;
  end;

  var curNum := 2;
  var prevNum := 1;

  for var i := 1 to x div 2 do
  begin
    if curNum * curNum > x then
      break;
    curNum += 1;
    prevNum += 1;
  end;

  if curNum * curNum = x then
    Result := curNum
  else
    Result := prevNum;
end;

