procedure Dfs(var grid: array of array of integer; i, j: integer);
begin
  if (i < 0) or (i >= grid.Length) or (j < 0) or (j >= grid[0].Length) or (grid[i][j] <> 1) then
    exit;

  grid[i][j] := -1;
  Dfs(grid, i+1, j);
  Dfs(grid, i-1, j);
  Dfs(grid, i, j+1);
  Dfs(grid, i, j-1);
end;

