      end;

  Result := islands;
end;

function IntegerSquareRoot(n: integer): integer;
begin
  if n < 0 then
    raise new System.ArgumentException('n must be non-negative');

  var x := n;
  var y := (x + 1) div 2;

  while y < x do
  begin
    x := y;
    y := (x + n div x) div 2;
  end;

  Result := x;
end;

function CountDecoding(s: string): integer;
begin
  if (s.Length = 0) or (s[1] = '0') then
  begin
    Result := 0;
    exit;
  end;

  var n := s.Length;
  var dp := ArrFill(n + 1, 0);
  dp[0] := 1;
  dp[1] := 1;

  for var i := 2 to n do
  begin
    var single := StrToInt(s[i].ToString);
    var double := StrToInt(s.Substring(i-1, 2));

    if (single >= 1) and (single <= 9) then
      dp[i] += dp[i - 1];

    if (double >= 10) and (double <= 26) then
      dp[i] += dp[i - 2];
  end;

  Result := dp[n];
end;

function TotalSubarrays(nums: array of integer; k: integer): integer;
