  countBySum[0] := 1;

  foreach var num in nums do
  begin
    s += num;
    if countBySum.ContainsKey(s - k) then
      kCount += countBySum[s - k];

    if countBySum.ContainsKey(s) then
      countBySum[s] += 1
    else
      countBySum[s] := 1;
  end;

  Result := kCount;
end;

function SumEvenProductOdd(numbers: array of integer): (integer, integer);
begin
  var sumEven := 0;
  var productOdd := 1;
  var hasOdd := false;

  foreach var number in numbers do
  begin
    if number mod 2 = 0 then
      sumEven += number
    else
    begin
      productOdd *= number;
      hasOdd := true;
    end;
  end;

  if not hasOdd then
    productOdd := 1;

  Result := (sumEven, productOdd);
end;

