function Helper(l, r: integer; delete: boolean; const s: string): boolean;
begin
  while l < r do
  begin
    if s[l + 1] <> s[r + 1] then
    begin
      if delete then
        Result := Helper(l, r-1, false, s) or Helper(l+1, r, false, s)
      else
        Result := false;
      exit;
    end;
    l += 1;
    r -= 1;
  end;
  Result := true;
end;

