function NumConsecutiveSum(n: integer): integer;
begin
  var count := 0;
  for var i := 1 to Round(Sqrt(2 * n)) do
  begin
    if (n - (i * (i - 1) div 2)) mod i = 0 then
    begin
      var value := (n - (i * (i - 1) div 2)) div i;
      if value > 0 then
        count += 1;
    end;
  end;
  Result := count;
end;

function NewtonSquareRoot(num: real): real;
begin
  if num < 0 then
  begin
    Result := -1;
    exit;
  end;

  var precision := 0.00000001;
  var x: real;

  if num < 1 then
    x := num
  else
    x := num / 2;

  while true do
  begin
    var nextX := (x + num / x) / 2;
    if Abs(nextX - x) < precision then
    begin
      Result := nextX;
      exit;
    end;
    x := nextX;
  end;
end;

function RotList(lst: array of integer; num: integer): List<integer>;
begin
  var n := lst.Length;
  var actualNum := num mod n;
  var rotated := lst.Skip(n - actualNum).Concat(lst.Take(n - actualNum)).ToList;
