function FindPivot(nums: array of integer): integer;
begin
  var left := 0;
  var right := nums.Length - 1;

  while left < right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] > nums[right] then
      left := mid + 1
    else
      right := mid;
  end;
  Result := left;
end;

function BinarySearch(nums: array of integer; target, left, right: integer): integer;
begin
  while left <= right do
  begin
    var mid := (left + right) div 2;
    if nums[mid] = target then
    begin
      Result := mid;
      exit;
    end
    else if nums[mid] < target then
      left := mid + 1
    else
      right := mid - 1;
  end;
  Result := -1;
end;

function FindInRotatedArray(nums: array of integer; target: integer): integer;
