  if (pivot = 0) or (target < nums[0]) then
    Result := BinarySearch(nums, target, pivot, nums.Length - 1)
  else
    Result := BinarySearch(nums, target, 0, pivot - 1);
end;

function LargestSubarrayLength(nums: array of integer; k: integer): integer;
