  begin
    if not win.ContainsKey(nums[j]) then
      win[nums[j]] := 0;

    if win[nums[j]] = 0 then
      k -= 1;

    win[nums[j]] += 1;

    while k < 0 do
    begin
      win[nums[i]] -= 1;
      if win[nums[i]] = 0 then
        k += 1;
      i += 1;
    end;

    ans := Max(ans, j - i + 1);
  end;

  Result := ans;
end;

