function DiceCombinations(n, s: integer): integer;
begin
  var dp := ArrFill(s + 1, 0);
  for var i := 1 to 6 do
    if i <= s then
      dp[i] := 1;

  for var i := 1 to n - 1 do
    for var j := s downto 1 do
    begin
      var sum := 0;
      for var k := Max(0, j - 6) to j - 1 do
        sum += dp[k];
      dp[j] := sum;
    end;

  Result := dp[s];
end;

