function GetShortestUniqueSubstring(arr: array of char; str: string): string;
begin
  var checkLength: integer := -1;
  var dic := new Dictionary<char, integer>;
  var output: string := '';

  foreach var item in arr do
    dic[item] := 1;

  for var index := 0 to str.Length - 1 do
  begin
    var item := str[index + 1];
    if dic.ContainsKey(item) then
      dic.Remove(item);

    if dic.Count = 0 then
    begin
      checkLength := index + 1;
      output := str.Substring(0, index + 1);
      break;
    end;
  end;

  if checkLength = -1 then
  begin
    Result := '';
    exit;
  end;

  var start := 1;
  checkLength -= 1;

  while start + checkLength <= str.Length do
  begin
    if Check(str.Substring(start - 1, checkLength), arr) then
    begin
      output := str.Substring(start - 1, checkLength);
      checkLength -= 1;
    end
    else
      start += 1;
  end;

  Result := output;
end;

