function FindClosestSum(nums: array of integer; target: integer): integer;
begin
  var tempNums := nums.ToList;
  tempNums.Sort;
  var closestSum := integer.MaxValue;

  for var i := 0 to tempNums.Count - 3 do
  begin
    var left := i + 1;
    var right := tempNums.Count - 1;

    while left < right do
    begin
      var currentSum := tempNums[i] + tempNums[left] + tempNums[right];
      if Abs(target - currentSum) < Abs(target - closestSum) then
        closestSum := currentSum;

      if currentSum < target then
        left += 1
      else if currentSum > target then
        right -= 1
      else
      begin
        Result := currentSum;
        exit;
      end;
    end;
  end;

  Result := closestSum;
end;

