function CountRotationsWithDuplicates(arr: array of integer): integer;
begin
  var start := 0;
  var finish := arr.Length - 1;

  while start < finish do
  begin
    var mid := start + (finish - start) div 2;

    if (mid < finish) and (arr[mid] > arr[mid + 1]) then
    begin
      Result := mid + 1;
      exit;
    end;

    if (mid > start) and (arr[mid - 1] > arr[mid]) then
    begin
      Result := mid;
      exit;
    end;

    if (arr[start] = arr[mid]) and (arr[finish] = arr[mid]) then
    begin
      if (start < arr.Length - 1) and (arr[start] > arr[start + 1]) then
      begin
        Result := start + 1;
        exit;
      end;
      start += 1;

      if (finish > 0) and (arr[finish - 1] > arr[finish]) then
      begin
        Result := finish;
        exit;
      end;
      finish -= 1;
    end
    else if (arr[start] < arr[mid]) or ((arr[start] = arr[mid]) and (arr[mid] > arr[finish])) then
      start := mid + 1
    else
      finish := mid - 1;
  end;

  Result := 0;
end;

