function CharacterReplacement(s: string; k: integer): integer;
begin
  var chCountInWindow := new Dictionary<char, integer>;
  var l := 0;
  var N := s.Length;
  var ans := 0;

  for var r := 0 to N - 1 do
  begin
    if not chCountInWindow.ContainsKey(s[r + 1]) then
      chCountInWindow[s[r + 1]] := 0;
    chCountInWindow[s[r + 1]] += 1;

    var windowSize := r - l + 1;
    var candidateSize := chCountInWindow.Values.Max;
    var nonCandidateSize := windowSize - candidateSize;

    if nonCandidateSize > k then
    begin
      chCountInWindow[s[l + 1]] -= 1;
      l += 1;
    end;

    windowSize := r - l + 1;
    ans := Max(ans, windowSize);
  end;

  Result := ans;
end;

