function MaxProfitWithKTransactions(prices: array of integer; k: integer): integer;
begin
  if prices.Length = 0 then
  begin
    Result := 0;
    exit;
  end;

  var buildDP := new integer[k + 1, prices.Length];

  for var row := 1 to k do
  begin
    var maxSeen := integer.MinValue;

    for var col := 1 to prices.Length - 1 do
    begin
      maxSeen := Max(maxSeen, -prices[col-1] + buildDP[row-1, col-1]);
      buildDP[row, col] := Max(buildDP[row, col-1], prices[col] + maxSeen);
    end;
  end;

  Result := buildDP[k, prices.Length - 1];
end;

