  var currentDepth := 1;
  var stack := new Stack<(integer, array of Object)>;

  foreach var item in lst do
  begin
    if item is array of Object then
    begin
      stack.Push((currentDepth, Arr(item)));
      currentDepth += 1;
      if currentDepth > maxDepth then
        maxDepth := currentDepth;
    end
    else
    begin
      while (stack.Count > 0) and not (item is array of Object) do
      begin
        var (depth, arr) := stack.Pop;
        currentDepth := depth;
      end;
    end;
  end;

  Result := maxDepth;
end;

