function IsValidBst(root: TreeNode): boolean;
begin
  if root = nil then
  begin
    Result := true;
    exit;
  end;

  var stack := new Stack<(TreeNode, real, real)>;
  stack.Push((root, real.MinValue, real.MaxValue));

  while stack.Count > 0 do
  begin
    var (node, lower, upper) := stack.Pop;
    if node = nil then
      continue;

    var value := node.val;
    if (value <= lower) or (value >= upper) then
    begin
      Result := false;
      exit;
    end;

    stack.Push((node.right, value, upper));
    stack.Push((node.left, lower, value));
  end;

  Result := true;
end;

