function Dfs(i, j: integer; var dp: array[,] of integer; const matrix: array of array of integer): integer;
begin
  if dp[i, j] <> -1 then
  begin
    Result := dp[i, j];
    exit;
  end;

  var directions := |(0,1), (0,-1), (1,0), (-1,0)|;
  dp[i, j] := 1;

  foreach var (dx, dy) in directions do
  begin
    var x := i + dx;
    var y := j + dy;

    if (x < 0) or (x >= matrix.Length) or (y < 0) or (y >= matrix[0].Length) or (matrix[x][y] <= matrix[i][j]) then
      continue;

    dp[i, j] := Max(dp[i, j], Dfs(x, y, dp, matrix) + 1);
  end;

  Result := dp[i, j];
end;

