procedure Union(x, y: integer; var parents: array of integer; var ranks: array of integer);
begin
  var px := Find(x, parents);
  var py := Find(y, parents);

  if px = py then
    exit;

  var rx := ranks[px];
  var ry := ranks[py];

  if rx < ry then
  begin
    var temp := px;
    px := py;
    py := temp;
  end;

  parents[py] := px;
  if rx = ry then
    ranks[px] += 1;
end;

