function MaxSum(left, right, mid: integer; const arr: array of integer): integer;
begin
  var sumLeft := integer.MinValue;
  var currentSum := 0;

  for var i := mid downto left do
  begin
    currentSum += arr[i];
    if currentSum > sumLeft then
      sumLeft := currentSum;
  end;

  var sumRight := integer.MinValue;
  currentSum := 0;

  for var i := mid + 1 to right do
  begin
    currentSum += arr[i];
    if currentSum > sumRight then
      sumRight := currentSum;
  end;

  Result := sumLeft + sumRight;
end;

function Solve(left, right: integer; const arr: array of integer): integer;
begin
  if left = right then
  begin
    Result := arr[left];
    exit;
  end;

  var mid := (left + right) div 2;
  var leftSum := Solve(left, mid, arr);
  var rightSum := Solve(mid + 1, right, arr);
  var crossingSum := MaxSum(left, right, mid, arr);

  Result := Max(Max(leftSum, rightSum), crossingSum);
end;

