function CheckPerfectCube(n: integer): boolean;
begin
  var root := Round(Power(n, 1/3));
  Result := n = root * root * root;
end;

function Hanoi(n: integer): integer;
begin
  if n = 1 then
    Result := 1
  else
    Result := 2 * Hanoi(n - 1) + 1;
end;

function IsPalindrome(s: string): boolean;
begin
  var cleaned := new StringBuilder;

  for var i := 1 to s.Length do
  begin
    var c := s[i];
    if c in ['a'..'z', 'A'..'Z', '0'..'9'] then
      cleaned.Append(c.ToLower);
  end;

  var cleanedStr := cleaned.ToString;
  Result := cleanedStr = new string(cleanedStr.Reverse.ToArray);
end;

function CountMedianSubarrays(nums: array of integer; k: integer): integer;
begin
  var n := nums.Length;
  var delta := ArrFill(n, 0);

  for var i := 0 to n - 1 do
  begin
    if nums[i] > k then
      delta[i] := 1
    else if nums[i] < k then
      delta[i] := -1
    else
      delta[i] := 0;
  end;

  try
    var idx := &Array.IndexOf(nums, k);
    var l := idx;
    var r := idx;

    var accum := new List<integer>;
    var sum := 0;
    for var i := 0 to n - 1 do
    begin
      sum += delta[i];
      accum.Add(sum);
    end;

    var cnt := new Dictionary<integer, integer>;
    for var i := 0 to idx - 1 do
    begin
      if cnt.ContainsKey(accum[i]) then
        cnt[accum[i]] += 1
      else
        cnt[accum[i]] := 1;
    end;

    if cnt.ContainsKey(0) then
      cnt[0] += 1
    else
      cnt[0] := 1;

    var res := 0;
    for var i := idx to n - 1 do
    begin
      if cnt.ContainsKey(accum[i]) then
        res += cnt[accum[i]];
      if cnt.ContainsKey(accum[i] - 1) then
        res += cnt[accum[i] - 1];
    end;

    Result := res;
  except
    Result := 0;
  end;
end;
